 Future<void> _load() async{
  final company=(widget.companyId??'').trim();if(company.isEmpty){setState(()=>_loading=false);_error='حدد الشركة لعرض سجلات هذا القسم.';return;}
  setState(()=>_loading=true);
  try{final data=await _db.from('erp_business_suite_records').select('*').eq('company_id',company).eq('module_key',_key).eq('record_type',_c.type).order('created_at',ascending:false).limit(1000);if(!mounted)return;setState(()=>_rows=(data as List).map((e)=>Map<String,dynamic>.from(e)).toList());}
  catch(e){_error='تعذر تحميل السجلات: $e';}finally{if(mounted)setState(()=>_loading=false);}
 }
